select case when year(sale_date) < 2024 then 'before_2024' when year(sale_date) = 2024 then '2024' else 'after_2024' end as sale_cohort, date_format(sale_date, 'yyyy-MM') as sale_month, max(sale_date) as last_sale_date from store_sales where product_id in (1, 6, 9, 10) or sale_date >= '2023-12-15' group by 1, 2 order by sale_month, sale_cohort limit 1
